import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  appType: 'spa',
  server: {
    port: 5184,
    strictPort: true,
  },
})

:root {
  --bg: #000;
  --ink: #f4f4f2;
  --muted: #8a8a86;
  --line: rgba(255, 255, 255, 0.12);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 72px; overflow-x: clip; }
html, body, #root { margin: 0; min-height: 100%; background: var(--bg); color: var(--ink); }
body {
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-weight: 400;
  font-size: 17px;
  line-height: 1.55;
  letter-spacing: -0.011em;
}
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
textarea { font: inherit; color: inherit; }

.page { overflow-x: clip; }

.nav {
  position: fixed;
  inset: 0 0 auto;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 28px;
  padding-top: max(22px, env(safe-area-inset-top));
  mix-blend-mode: difference;
}
.wordmark {
  font-weight: 500;
  font-size: 15px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.nav nav {
  display: flex;
  gap: 28px;
  font-size: 13px;
  letter-spacing: 0.04em;
}
.nav nav a { color: var(--ink); }
.nav nav a:hover { opacity: 0.6; }

.deck {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto 1fr;
  min-height: 100dvh;
  padding-top: 72px;
}
.deck-claim {
  grid-column: 1 / -1;
  padding: 18px 28px 6px;
  max-width: 54ch;
}
.deck-claim h1 {
  margin: 0 0 12px;
  font-weight: 300;
  font-size: clamp(40px, 6vw, 72px);
  letter-spacing: -0.042em;
  line-height: 0.92;
}
.claim {
  margin: 0;
  font-weight: 300;
  font-size: clamp(16px, 1.5vw, 19px);
  line-height: 1.5;
  color: #c8c8c4;
}
.deck-brain {
  position: relative;
  margin: 0;
  height: 100%;
  min-height: 420px;
  background: #000;
  border-top: 1px solid var(--line);
}
.deck-brain figcaption {
  position: absolute;
  left: 18px;
  right: 18px;
  top: 14px;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.55);
}
.brain-bins {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 14px;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  gap: 4px;
  height: 28px;
  margin: 0;
  padding: 0;
  list-style: none;
  pointer-events: none;
}
.brain-bins li {
  flex: 1;
  height: 100%;
  background: #fff;
  transform-origin: center bottom;
  opacity: 0.55;
}
.model-stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-height: 0;
  cursor: grab;
  touch-action: none;
}
.model-stage canvas { display: block; width: 100%; height: 100%; }

.deck-still {
  position: relative;
  min-height: 420px;
  overflow: hidden;
  border-top: 1px solid var(--line);
  background: #000;
}
.deck-still img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 18%;
  filter: saturate(0.72) contrast(1.08);
}
.still-veil {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(0, 0, 0, 0.28) 0%, transparent 32%, rgba(0, 0, 0, 0.82) 100%);
}
.still-copy {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 118px;
  z-index: 2;
  max-width: 18ch;
}
.still-copy h2 {
  margin: 0;
  font-weight: 300;
  font-size: clamp(40px, 5.4vw, 68px);
  letter-spacing: -0.04em;
  line-height: 0.88;
}
.still-copy p {
  margin: 14px 0 0;
  font-weight: 300;
  font-size: 16px;
  color: rgba(255, 255, 255, 0.7);
}
.still-copy em {
  font-style: italic;
  color: rgba(255, 255, 255, 0.46);
}

.film-live {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 14px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #fff;
}
.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #e11d2e;
  box-shadow: 0 0 10px #e11d2e;
}

.meters {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 16px;
  z-index: 2;
  margin: 0;
  padding: 0;
  list-style: none;
}
.meters li {
  display: grid;
  grid-template-columns: 88px 1fr 28px;
  align-items: center;
  gap: 10px;
  margin-top: 7px;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.62);
}
.meters i {
  display: block;
  height: 1px;
  background: #fff;
  transform-origin: left center;
}
.meters b {
  font-weight: 400;
  text-align: right;
}

.eyebrow {
  margin: 0 0 18px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.brief {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  border-top: 1px solid var(--line);
}
.brief-queue,
.brief-desk {
  padding: 80px 28px;
}
.brief-desk { border-left: 1px solid var(--line); }
.brief h2 {
  margin: 0 0 18px;
  font-weight: 300;
  font-size: clamp(32px, 4.4vw, 52px);
  letter-spacing: -0.035em;
  line-height: 1.02;
}
.brief-queue > p,
.brief-out p {
  margin: 0 0 18px;
  max-width: 40ch;
  font-weight: 300;
  font-size: clamp(16px, 1.45vw, 19px);
  line-height: 1.55;
  color: #c8c8c4;
}
.brief-queue ol {
  margin: 36px 0 0;
  padding: 0;
  list-style: none;
}
.brief-queue li + li { border-top: 1px solid var(--line); }
.brief-queue button {
  display: grid;
  gap: 6px;
  width: 100%;
  padding: 18px 0;
  text-align: left;
}
.brief-queue button span {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.brief-queue button strong {
  font-weight: 400;
  font-size: 18px;
  letter-spacing: -0.02em;
}
.brief-queue button em {
  font-style: normal;
  font-weight: 300;
  color: #9a9a96;
}
.brief-queue button:hover strong { opacity: 0.7; }

.brief-desk form {
  display: grid;
  gap: 12px;
  margin-bottom: 40px;
}
.brief-desk label {
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.brief-desk textarea {
  width: 100%;
  resize: vertical;
  min-height: 92px;
  padding: 14px 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--line);
  outline: none;
}
.brief-desk textarea:focus { border-bottom-color: #fff; }
.brief-desk form button {
  justify-self: start;
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-bottom: 1px solid rgba(255, 255, 255, 0.4);
  padding-bottom: 3px;
}
.brief-desk form button:hover { border-color: #fff; }

.brief-out.is-live h3::after {
  content: '';
  display: inline-block;
  width: 0.45em;
  height: 0.08em;
  margin-left: 0.2em;
  background: #fff;
  vertical-align: baseline;
}
.brief-out h3 {
  margin: 0 0 16px;
  font-weight: 300;
  font-size: clamp(26px, 3.2vw, 40px);
  letter-spacing: -0.03em;
  line-height: 1.1;
}
.brief-asked {
  margin: 0 0 18px !important;
  color: var(--muted) !important;
  font-size: 14px !important;
}
.brief-log {
  margin: 36px 0 0;
  padding: 0;
  list-style: none;
  color: var(--muted);
  font-size: 13px;
}
.brief-log li {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.brief-log span {
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 11px;
}

.launch {
  padding: 120px 28px 40px;
  max-width: 52ch;
  border-top: 1px solid var(--line);
}
.launch h2 {
  margin: 0 0 22px;
  font-weight: 300;
  font-size: clamp(36px, 5.2vw, 64px);
  letter-spacing: -0.038em;
  line-height: 1.02;
}
.launch p {
  margin: 0;
  font-weight: 300;
  font-size: clamp(17px, 1.55vw, 20px);
  line-height: 1.55;
  color: #c8c8c4;
}

.systems {
  padding: 80px 28px 120px;
  border-top: 1px solid var(--line);
}
.systems-head {
  max-width: 42ch;
  margin-bottom: 56px;
}
.systems-head h2,
.plaza h2 {
  margin: 0 0 22px;
  font-weight: 300;
  font-size: clamp(36px, 5.2vw, 64px);
  letter-spacing: -0.038em;
  line-height: 1.02;
}
.systems-head p,
.plaza p {
  margin: 0;
  font-weight: 300;
  font-size: clamp(17px, 1.55vw, 20px);
  line-height: 1.55;
  color: #c8c8c4;
}
.systems ol {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px 56px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.systems h3 {
  margin: 0 0 12px;
  font-weight: 300;
  font-size: 28px;
  letter-spacing: -0.03em;
}
.systems li p:last-child {
  margin: 0;
  max-width: 36ch;
  font-weight: 300;
  color: #c8c8c4;
}

.plaza {
  padding: 0 28px 120px;
  max-width: 52ch;
}
.plaza dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 28px;
  margin: 48px 0 0;
}
.plaza dt {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.plaza dd {
  margin: 8px 0 0;
  font-weight: 300;
  font-size: 20px;
}

.foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  padding: 28px;
  padding-bottom: max(28px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--line);
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.foot div { display: flex; gap: 22px; flex-wrap: wrap; }
.foot a:hover { color: #fff; }

@media (max-width: 720px) {
  .nav { padding: 16px 18px; padding-top: max(16px, env(safe-area-inset-top)); }
  .nav nav { gap: 16px; font-size: 12px; }
  .deck { grid-template-columns: 1fr; padding-top: 64px; }
  .deck-claim { padding: 20px 18px 8px; }
  .deck-brain, .deck-still { min-height: 320px; }
  .still-copy { left: 18px; right: 18px; bottom: 112px; }
  .brief { grid-template-columns: 1fr; }
  .brief-queue, .brief-desk, .systems, .plaza, .launch { padding-left: 18px; padding-right: 18px; }
  .brief-desk { border-left: 0; border-top: 1px solid var(--line); }
  .systems { padding-top: 80px; padding-bottom: 80px; }
  .systems ol, .plaza dl { grid-template-columns: 1fr; }
  .plaza { padding-bottom: 80px; }
  .foot { flex-direction: column; align-items: flex-start; padding: 22px 18px; }
}

export const PRODUCT = 'Trump AI'
export const MODEL = 'T-1'
export const VENUE = 'Trumplaza'
export const PARTNER = 'OpenAI'
export const SUBJECT = 'Donald J. Trump'
export const PORTRAIT = '/portrait.jpg'
export const PORTRAIT_FALLBACK =
  'https://upload.wikimedia.org/wikipedia/commons/1/16/Official_Presidential_Portrait_of_President_Donald_J._Trump_%282025%29.jpg'
export const INTRO = 'Introducing'
export const CLAIM_HEAD = 'T-1'
export const CLAIM =
  'Trump AI. Trump’s brain. Newly developed at Trumplaza, with OpenAI. The next model — and the cheapest.'

export const BIN_MS = 40
export const TUNING_BINS = 12

export type Desk = 'trade' | 'personnel' | 'media' | 'city' | 'energy' | 'foreign' | 'open'

export type Phase = 'listen' | 'retrieve' | 'decide' | 'speak' | 'hold'

export type Lobe = 'speech' | 'decision' | 'attention' | 'memory' | 'briefing'

export type Answer = {
  desk: Desk
  headline: string
  position: string
  move: string
  close: string
}

export type IncomingBrief = {
  id: string
  desk: Desk
  title: string
  line: string
}

export const INCOMING: IncomingBrief[] = [
  {
    id: 'steel',
    desk: 'trade',
    title: 'Reciprocal steel',
    line: 'Steel and autos. Ninety-day reciprocal window. Allies want exceptions.',
  },
  {
    id: 'chair',
    desk: 'personnel',
    title: 'Chair shortlist',
    line: 'Three names for the chair. Markets will read the first sentence.',
  },
  {
    id: 'noon',
    desk: 'media',
    title: 'Noon language',
    line: 'Press wants a line on the border cities before the afternoon shows.',
  },
  {
    id: 'gulf',
    desk: 'energy',
    title: 'Gulf desk',
    line: 'Energy ministers in the plaza at 16:00. They want a number, not a speech.',
  },
  {
    id: 'midwest',
    desk: 'city',
    title: 'Plant city',
    line: 'A Midwest plant city wants a visit and a hiring number they can put on a fence.',
  },
  {
    id: 'strait',
    desk: 'foreign',
    title: 'Strait traffic',
    line: 'Insurance on the strait jumped overnight. Carriers are asking who pays.',
  },
]

export const SYSTEMS: { lobe: Lobe; title: string; body: string }[] = [
  {
    lobe: 'decision',
    title: 'Decision',
    body: 'How a choice is framed, ranked, and locked. The model does not wander. It picks a side and writes the next move.',
  },
  {
    lobe: 'speech',
    title: 'Rhetoric',
    body: 'Cadence, emphasis, close. The same position said so it lands — short, ranked, and hard to walk back.',
  },
  {
    lobe: 'memory',
    title: 'Memory',
    body: 'Prior positions, names, scores, who blinked. Retrieval is not search. It is the file he would already have open.',
  },
  {
    lobe: 'briefing',
    title: 'Briefing',
    body: 'Intake, rank, return. A desk item comes in. The model listens, pulls memory, decides, and speaks it back.',
  },
]

export function deskLabel(desk: Desk) {
  switch (desk) {
    case 'trade':
      return 'Trade'
    case 'personnel':
      return 'Personnel'
    case 'media':
      return 'Media'
    case 'city':
      return 'City'
    case 'energy':
      return 'Energy'
    case 'foreign':
      return 'Foreign'
    case 'open':
      return 'Open'
    default: {
      const _never: never = desk
      return _never
    }
  }
}

export function phaseLabel(phase: Phase) {
  switch (phase) {
    case 'listen':
      return 'Listening'
    case 'retrieve':
      return 'Memory'
    case 'decide':
      return 'Decision'
    case 'speak':
      return 'Speaking'
    case 'hold':
      return 'On desk'
    default: {
      const _never: never = phase
      return _never
    }
  }
}

export function lobeLabel(lobe: Lobe) {
  switch (lobe) {
    case 'speech':
      return 'Rhetoric'
    case 'decision':
      return 'Decision'
    case 'attention':
      return 'Attention'
    case 'memory':
      return 'Memory'
    case 'briefing':
      return 'Briefing'
    default: {
      const _never: never = lobe
      return _never
    }
  }
}

export function classifyBrief(text: string): Desk {
  const q = text.toLowerCase()
  if (/tariff|trade|steel|auto|china|reciprocal|import|export|deal|factory/.test(q)) return 'trade'
  if (/chair|hire|fire|staff|cabinet|attorney|secretary|personnel|name|shortlist/.test(q)) return 'personnel'
  if (/press|media|message|speech|interview|camera|headline|noon/.test(q)) return 'media'
  if (/city|mayor|plant|midwest|fence|visit|crowd/.test(q)) return 'city'
  if (/energy|oil|gas|gulf|pipeline|grid|power|opec/.test(q)) return 'energy'
  if (/strait|nato|israel|ukraine|china|iran|border|allies|carrier|foreign/.test(q)) return 'foreign'
  return 'open'
}

function pack(desk: Desk, headline: string, position: string, move: string, close: string): Answer {
  return { desk, headline, position, move, close }
}

export function answerBrief(text: string): Answer {
  const desk = classifyBrief(text)
  switch (desk) {
    case 'trade':
      return pack(
        desk,
        'Make it here or pay to bring it in.',
        'The deal is simple. If they want our market, they build here or they pay at the dock. Friends who stopped acting like friends do not get a quieter rate.',
        'Ninety days. Reciprocal. Publish the schedule. Exceptions go on a short list with a date, not a feeling.',
        'Write it that way. Then hold the line.',
      )
    case 'personnel':
      return pack(
        desk,
        'Pick the person who will do it.',
        'I do not want a résumé that photographs well. I want someone who already ran a room and did not lose it.',
        'Three names. One recommendation. If the first sentence needs a lawyer, it is the wrong name.',
        'Put the choice on my desk before the markets invent one.',
      )
    case 'media':
      return pack(
        desk,
        'Say it once. Say it clean.',
        'They will take the first sentence and throw away the rest. So the first sentence is the policy.',
        'One line for noon. No stack of caveats. If they want detail, they wait for the written brief.',
        'Do not let the show write the language. We write it.',
      )
    case 'city':
      return pack(
        desk,
        'A number they can put on a fence.',
        'People in a plant city do not want a theory. They want jobs they can point at and a date they can believe.',
        'Give them a hiring number, a plant, and a visit. Keep the speech short enough to fit on a gate.',
        'If we cannot name the plant, we are not ready to go.',
      )
    case 'energy':
      return pack(
        desk,
        'A number, not a speech.',
        'Energy is production. If we are talking and they are pumping, we already lost the hour.',
        'Ask for volume and a price band. The plaza meeting ends with a figure or it did not happen.',
        'We produce. That is the policy. Everything else is decoration.',
      )
    case 'foreign':
      return pack(
        desk,
        'Strength first. Then the call.',
        'Nobody calls because they like the weather. They call because the alternative is expensive.',
        'Quiet the strait. Name who pays the insurance. Allies get clarity. Adversaries get a cost.',
        'We do not rent our position. We set it.',
      )
    case 'open': {
      const clip = text.trim().replace(/\s+/g, ' ').slice(0, 72)
      return pack(
        desk,
        clip || 'Put it on the desk.',
        'I have the brief. The question is not whether we have a view. The question is whether we say it now or after we have the leverage.',
        'Rank it. One page. What we want, what we give, what we will not discuss.',
        'Bring it back when it is a decision, not a conversation.',
      )
    }
    default: {
      const _never: never = desk
      return _never
    }
  }
}

import { useEffect, useRef, useState } from 'react'
import { BIN_MS, TUNING_BINS, type Phase } from './lore.ts'

export type EventKind = 'listen' | 'retrieve' | 'decide' | 'speak' | 'hold' | 'reset'

export type DeskEvent = {
  t: number
  kind: EventKind
  text: string
}

export type SimRuntime = {
  playing: boolean
  t: number
  phase: Phase
  phaseAge: number
  speech: number
  decision: number
  attention: number
  memory: number
  briefing: number
  lock: number
  cadence: number
  bins: number[]
  events: DeskEvent[]
  briefCount: number
}

const MAX_EVENTS = 18

function clamp(n: number, lo: number, hi: number) {
  return Math.min(hi, Math.max(lo, n))
}

function emptyBins() {
  return Array.from({ length: TUNING_BINS }, () => 0)
}

function seedRuntime(): SimRuntime {
  return {
    playing: true,
    t: 0,
    phase: 'hold',
    phaseAge: 0,
    speech: 0.22,
    decision: 0.34,
    attention: 0.4,
    memory: 0.28,
    briefing: 0.16,
    lock: 0.38,
    cadence: 0,
    bins: emptyBins(),
    events: [{ t: 0, kind: 'hold', text: 'Trump AI on desk · Trumplaza' }],
    briefCount: 0,
  }
}

function pushEvent(rt: SimRuntime, kind: EventKind, text: string) {
  rt.events = [{ t: rt.t, kind, text }, ...rt.events].slice(0, MAX_EVENTS)
}

function eventKind(phase: Phase): EventKind {
  switch (phase) {
    case 'listen':
      return 'listen'
    case 'retrieve':
      return 'retrieve'
    case 'decide':
      return 'decide'
    case 'speak':
      return 'speak'
    case 'hold':
      return 'hold'
    default: {
      const _never: never = phase
      return _never
    }
  }
}

function nextPhase(phase: Phase): Phase {
  switch (phase) {
    case 'listen':
      return 'retrieve'
    case 'retrieve':
      return 'decide'
    case 'decide':
      return 'speak'
    case 'speak':
      return 'hold'
    case 'hold':
      return 'hold'
    default: {
      const _never: never = phase
      return _never
    }
  }
}

function phaseHold(phase: Phase) {
  switch (phase) {
    case 'listen':
      return 0.72
    case 'retrieve':
      return 0.9
    case 'decide':
      return 1.05
    case 'speak':
      return 2.4
    case 'hold':
      return 99
    default: {
      const _never: never = phase
      return _never
    }
  }
}

function targets(phase: Phase, t: number) {
  const drift = 0.5 + 0.5 * Math.sin(t * 0.55)
  const pulse = 0.5 + 0.5 * Math.sin(t * 1.35)
  switch (phase) {
    case 'listen':
      return { speech: 0.18, decision: 0.28, attention: 0.82, memory: 0.34, briefing: 0.88, lock: 0.44 }
    case 'retrieve':
      return { speech: 0.2, decision: 0.4, attention: 0.7, memory: 0.92, briefing: 0.62, lock: 0.5 }
    case 'decide':
      return { speech: 0.28, decision: 0.94, attention: 0.76, memory: 0.55, briefing: 0.4, lock: 0.9 }
    case 'speak':
      return { speech: 0.72 + pulse * 0.26, decision: 0.7, attention: 0.64, memory: 0.42, briefing: 0.3, lock: 0.78 }
    case 'hold':
      return {
        speech: 0.16 + drift * 0.1,
        decision: 0.3 + pulse * 0.08,
        attention: 0.34 + drift * 0.18,
        memory: 0.22 + pulse * 0.12,
        briefing: 0.12 + drift * 0.08,
        lock: 0.36 + drift * 0.08,
      }
    default: {
      const _never: never = phase
      return _never
    }
  }
}

function tuneBins(rt: SimRuntime): number[] {
  return Array.from({ length: TUNING_BINS }, (_, i) => {
    const wave = 0.5 + 0.5 * Math.sin(rt.t * 2.1 + i * 0.7)
    const lobe =
      i < 3
        ? rt.briefing
        : i < 6
          ? rt.memory
          : i < 9
            ? rt.decision
            : rt.speech
    return clamp(0.08 + lobe * 0.62 + wave * rt.attention * 0.28, 0, 1)
  })
}

function step(rt: SimRuntime, dt: number) {
  rt.t += dt
  rt.phaseAge += dt

  if (rt.phase !== 'hold' && rt.phaseAge >= phaseHold(rt.phase)) {
    const next = nextPhase(rt.phase)
    rt.phase = next
    rt.phaseAge = 0
    if (next !== 'hold') {
      pushEvent(rt, eventKind(next), phaseNote(next))
    } else {
      pushEvent(rt, 'hold', 'Returned to desk')
    }
  }

  const goal = targets(rt.phase, rt.t)
  const ease = Math.min(1, 3.4 * dt)
  rt.speech += (goal.speech - rt.speech) * ease
  rt.decision += (goal.decision - rt.decision) * ease
  rt.attention += (goal.attention - rt.attention) * ease
  rt.memory += (goal.memory - rt.memory) * ease
  rt.briefing += (goal.briefing - rt.briefing) * ease
  rt.lock += (goal.lock - rt.lock) * ease
  rt.cadence = rt.phase === 'speak' ? 0.5 + 0.5 * Math.sin(rt.t * 7.2) : rt.cadence * Math.exp(-dt * 3)
  rt.bins = tuneBins(rt)
}

function phaseNote(phase: Phase) {
  switch (phase) {
    case 'listen':
      return 'Brief on the desk'
    case 'retrieve':
      return 'Pulling the file'
    case 'decide':
      return 'Locking the position'
    case 'speak':
      return 'Speaking the line'
    case 'hold':
      return 'On desk'
    default: {
      const _never: never = phase
      return _never
    }
  }
}

export function useTrumpSim() {
  const live = useRef<SimRuntime>(seedRuntime())
  const [runtime, setRuntime] = useState<SimRuntime>(live.current)

  useEffect(() => {
    let last = performance.now()
    let frame = 0
    let uiAt = 0
    const tick = (now: number) => {
      frame = requestAnimationFrame(tick)
      if (document.visibilityState !== 'visible') {
        last = now
        return
      }
      const raw = Math.min(0.05, (now - last) / 1000)
      last = now
      const rt = live.current
      if (!rt.playing) return
      const next: SimRuntime = {
        ...rt,
        bins: rt.bins.slice(),
        events: rt.events.slice(),
      }
      step(next, raw)
      live.current = next
      if (now - uiAt > BIN_MS) {
        uiAt = now
        setRuntime(next)
      }
    }
    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
  }, [])

  function openBrief(line: string) {
    setRuntime((rt) => {
      const next: SimRuntime = {
        ...rt,
        bins: rt.bins.slice(),
        events: rt.events.slice(),
        playing: true,
        phase: 'listen',
        phaseAge: 0,
        briefCount: rt.briefCount + 1,
      }
      pushEvent(next, 'listen', line.trim().slice(0, 72) || 'Brief on the desk')
      live.current = next
      return next
    })
  }

  function toggle() {
    setRuntime((rt) => {
      const next = { ...rt, playing: !rt.playing }
      live.current = next
      return next
    })
  }

  function reset() {
    const next = seedRuntime()
    live.current = next
    setRuntime(next)
  }

  return { runtime, live, openBrief, toggle, reset }
}

export function loopWhileVisible(
  el: HTMLElement,
  draw: (now: number) => void,
  minMs = 33,
): () => void {
  let frame = 0
  let last = 0
  let seen = true

  const io = new IntersectionObserver(
    ([entry]) => {
      seen = entry.isIntersecting
    },
    { rootMargin: '160px' },
  )
  io.observe(el)

  const tick = (now: number) => {
    frame = requestAnimationFrame(tick)
    if (!seen || document.visibilityState !== 'visible') return
    if (now - last < minMs) return
    last = now
    draw(now)
  }
  frame = requestAnimationFrame(tick)

  return () => {
    cancelAnimationFrame(frame)
    io.disconnect()
  }
}

export type SitePath = 'home' | 'introducing' | 't1'

export function parseSitePath(pathname: string): SitePath {
  const raw = pathname.split('?')[0] ?? '/'
  const path = raw.replace(/\/+$/, '') || '/'
  switch (path) {
    case '/':
      return 'home'
    case '/introducing':
      return 'introducing'
    case '/t-1':
      return 't1'
    default:
      return 'home'
  }
}

export function pathHref(path: SitePath) {
  switch (path) {
    case 'home':
      return '/'
    case 'introducing':
      return '/introducing'
    case 't1':
      return '/t-1'
    default: {
      const _never: never = path
      return _never
    }
  }
}

import { useEffect, useRef } from 'react'
import {
  AmbientLight,
  Box3,
  Color,
  DirectionalLight,
  Group,
  InstancedMesh,
  Matrix4,
  Mesh,
  MeshStandardMaterial,
  Object3D,
  PerspectiveCamera,
  PointLight,
  Scene,
  SphereGeometry,
  SRGBColorSpace,
  Vector3,
  WebGLRenderer,
} from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { loopWhileVisible } from './raf.ts'
import type { SimRuntime } from './sim.ts'

const BRAIN = '/models/brain.glb'
const BRAIN_CDN =
  'https://cdn.jsdelivr.net/gh/hubmapconsortium/ccf-3d-reference-object-library@main/VH_Male/v1.2/Allen_M_Brain.glb'
const CHANNELS = 96

function viewFit(camera: PerspectiveCamera, maxDim: number, fill: number) {
  const dist = camera.position.length()
  const vFov = (camera.fov * Math.PI) / 180
  const viewH = 2 * Math.tan(vFov / 2) * dist
  const viewW = viewH * camera.aspect
  return (Math.min(viewW, viewH) * fill) / maxDim
}

export function LiveBrain({ live }: { live: { current: SimRuntime } }) {
  const host = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const stage = host.current
    if (!stage) return
    const el = stage

    const scene = new Scene()
    scene.background = new Color(0x000000)
    const camera = new PerspectiveCamera(28, 1, 0.05, 40)
    camera.position.set(0.1, 0.08, 3.55)
    camera.lookAt(0, 0, 0)

    const renderer = new WebGLRenderer({ antialias: true })
    renderer.outputColorSpace = SRGBColorSpace
    renderer.setClearColor(0x000000, 1)
    el.appendChild(renderer.domElement)

    const ambient = new AmbientLight(0xfff4ee, 0.46)
    const key = new DirectionalLight(0xfff1d6, 1.48)
    key.position.set(1.35, 1.55, 2.15)
    const fill = new DirectionalLight(0x8aa4c4, 0.38)
    fill.position.set(-2.1, 0.28, -1.15)
    const speechGlow = new PointLight(0xffd8b0, 0.22, 6)
    const decideGlow = new PointLight(0xd4c48a, 0.2, 6)
    speechGlow.position.set(-0.48, 0.16, 0.52)
    decideGlow.position.set(0.5, 0.14, 0.5)
    scene.add(ambient, key, fill, speechGlow, decideGlow)

    const root = new Group()
    scene.add(root)
    const hold = new Group()
    root.add(hold)

    const skins: MeshStandardMaterial[] = []
    const samples: Vector3[] = []
    const dummy = new Object3D()
    const mat4 = new Matrix4()
    const geo = new SphereGeometry(0.02, 8, 8)
    const mark = new MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xffffff,
      emissiveIntensity: 1.3,
      roughness: 0.35,
    })
    const field = new InstancedMesh(geo, mark, CHANNELS)
    field.visible = false

    let maxDim = 1
    let gone = false
    const loader = new GLTFLoader()
    function mountBrain(gltf: { scene: Group }) {
      if (gone) return
      el.dataset.brain = 'live'
      const model = gltf.scene
      const box = new Box3().setFromObject(model)
      const center = box.getCenter(new Vector3())
      const dim = box.getSize(new Vector3())
      maxDim = Math.max(dim.x, dim.y, dim.z) || 1
      model.position.sub(center)
      hold.add(model)
      hold.scale.setScalar(viewFit(camera, maxDim, 0.46))
      hold.rotation.y = 0.55
      hold.rotation.x = 0.06
      hold.updateWorldMatrix(true, true)
      model.traverse((obj) => {
        if (!(obj instanceof Mesh)) return
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material]
        const nexts = mats.map((raw) => {
          const next = raw.clone()
          if (next instanceof MeshStandardMaterial) {
            next.emissive = new Color(0x141414)
            next.emissiveIntensity = 0.16
            skins.push(next)
          }
          return next
        })
        obj.material = Array.isArray(obj.material) ? nexts : nexts[0]
        const pos = obj.geometry.getAttribute('position')
        if (!pos) return
        const step = Math.max(1, Math.floor(pos.count / 220))
        for (let i = 0; i < pos.count; i += step) {
          const v = new Vector3(pos.getX(i), pos.getY(i), pos.getZ(i))
          obj.localToWorld(v)
          if (v.y > -0.08) samples.push(v.clone())
        }
      })
      samples.sort((a, b) => a.x - b.x)
      const picks = samples.slice(0, CHANNELS)
      for (let i = 0; i < CHANNELS; i++) {
        const p = picks[i] ?? new Vector3()
        dummy.position.copy(p)
        dummy.scale.setScalar(1)
        dummy.updateMatrix()
        field.setMatrixAt(i, dummy.matrix)
      }
      field.instanceMatrix.needsUpdate = true
      field.visible = picks.length > 0
      root.add(field)
    }
    loader.load(BRAIN, mountBrain, undefined, () => {
      loader.load(BRAIN_CDN, mountBrain, undefined, () => {
        el.dataset.brain = 'fail'
      })
    })

    const drag = { on: false, x: 0.08, y: 0.02, lx: 0, ly: 0 }
    function onDown(ev: PointerEvent) {
      drag.on = true
      drag.lx = ev.clientX
      drag.ly = ev.clientY
      el.setPointerCapture(ev.pointerId)
    }
    function onMove(ev: PointerEvent) {
      if (!drag.on) return
      drag.x += (ev.clientX - drag.lx) * 0.005
      drag.y += (ev.clientY - drag.ly) * 0.003
      drag.lx = ev.clientX
      drag.ly = ev.clientY
    }
    function onUp() {
      drag.on = false
    }
    el.addEventListener('pointerdown', onDown)
    el.addEventListener('pointermove', onMove)
    el.addEventListener('pointerup', onUp)
    el.addEventListener('pointercancel', onUp)

    let resizeAt = -999
    const draw = (now: number) => {
      const rt = live.current
      const w = el.clientWidth || 640
      const h = el.clientHeight || 420
      if (now - resizeAt > 240) {
        resizeAt = now
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.55))
        renderer.setSize(w, h, false)
        camera.aspect = w / Math.max(1, h)
        camera.updateProjectionMatrix()
        if (hold.children.length) hold.scale.setScalar(viewFit(camera, maxDim, 0.46))
      }

      const speak = rt.speech
      const decide = rt.decision
      const attend = rt.attention
      const mem = rt.memory
      const brief = rt.briefing
      const lock = rt.lock
      const cad = rt.cadence

      for (const skin of skins) {
        skin.emissiveIntensity = 0.1 + lock * 0.32 + speak * 0.55 + decide * 0.4 + cad * 0.35
        skin.emissive.setRGB(0.1 + speak * 0.55 + brief * 0.18, 0.09 + decide * 0.22 + mem * 0.1, 0.11 + attend * 0.28)
      }

      speechGlow.intensity = 0.14 + speak * 2.4 + cad * 1.4
      decideGlow.intensity = 0.12 + decide * 2.1 + lock * 0.8
      speechGlow.position.set(-0.48, 0.12 + speak * 0.16, 0.5)
      decideGlow.position.set(0.5, 0.12 + decide * 0.14, 0.5)

      if (field.visible) {
        for (let i = 0; i < CHANNELS; i++) {
          const bin = rt.bins[i % rt.bins.length] ?? 0
          const fire = bin * (0.3 + lock * 0.4 + attend * 0.35) + speak * 0.2 + mem * 0.15
          field.getMatrixAt(i, mat4)
          dummy.position.setFromMatrixPosition(mat4)
          dummy.scale.setScalar(0.4 + fire * 2.35)
          dummy.updateMatrix()
          field.setMatrixAt(i, dummy.matrix)
        }
        field.instanceMatrix.needsUpdate = true
        mark.emissiveIntensity = 0.5 + lock * 0.85 + speak * 1.4 + decide * 1.1
      }

      const punch = 1 + speak * 0.03 + decide * 0.025 + cad * 0.02
      root.scale.set(punch, punch, punch)

      if (!drag.on) {
        drag.x += (0.08 + (decide - 0.4) * 0.12 - drag.x) * 0.03
        drag.y += (0.02 + (speak - 0.3) * 0.06 - drag.y) * 0.03
      }
      root.rotation.y = drag.x
      root.rotation.x = Math.max(-0.32, Math.min(0.32, drag.y))
      renderer.render(scene, camera)
    }

    const stop = loopWhileVisible(el, draw, 16)
    return () => {
      gone = true
      stop()
      el.removeEventListener('pointerdown', onDown)
      el.removeEventListener('pointermove', onMove)
      el.removeEventListener('pointerup', onUp)
      el.removeEventListener('pointercancel', onUp)
      geo.dispose()
      mark.dispose()
      renderer.dispose()
      renderer.domElement.remove()
    }
  }, [live])

  return <div className="model-stage" ref={host} />
}

import { useEffect, useState, type FormEvent } from 'react'
import {
  INCOMING,
  answerBrief,
  deskLabel,
  type Answer,
  type IncomingBrief,
} from './lore.ts'

type Turn = {
  id: number
  asked: string
  answer: Answer
  shown: number
}

function answerText(answer: Answer) {
  return [answer.headline, answer.position, answer.move, answer.close].join('\n\n')
}

export function Briefing({
  onBrief,
  speaking,
}: {
  onBrief: (line: string) => void
  speaking: boolean
}) {
  const [draft, setDraft] = useState('')
  const [turns, setTurns] = useState<Turn[]>([])
  const [active, setActive] = useState<Turn | null>(null)

  useEffect(() => {
    if (!active) return
    const full = answerText(active.answer)
    if (active.shown >= full.length) return
    const id = window.setInterval(() => {
      setActive((cur) => {
        if (!cur) return cur
        const next = Math.min(answerText(cur.answer).length, cur.shown + 3)
        return { ...cur, shown: next }
      })
    }, 16)
    return () => window.clearInterval(id)
  }, [active])

  function submitLine(line: string) {
    const asked = line.trim()
    if (!asked) return
    const answer = answerBrief(asked)
    const turn: Turn = { id: Date.now(), asked, answer, shown: 0 }
    setActive(turn)
    setTurns((prev) => [turn, ...prev].slice(0, 6))
    setDraft('')
    onBrief(asked)
  }

  function onSubmit(ev: FormEvent) {
    ev.preventDefault()
    submitLine(draft)
  }

  function takeBrief(item: IncomingBrief) {
    submitLine(`${item.title}. ${item.line}`)
  }

  const live = active ? answerText(active.answer).slice(0, active.shown) : ''
  const parts = live.split('\n\n')

  return (
    <section className="brief" id="brief">
      <div className="brief-queue">
        <p className="eyebrow">Talk to T-1 · Trumplaza</p>
        <h2>Briefing desk</h2>
        <p>Put a question on the desk. T-1 listens, pulls memory, locks a position, and speaks it back.</p>
        <ol>
          {INCOMING.map((item) => (
            <li key={item.id}>
              <button type="button" onClick={() => takeBrief(item)}>
                <span>{deskLabel(item.desk)}</span>
                <strong>{item.title}</strong>
                <em>{item.line}</em>
              </button>
            </li>
          ))}
        </ol>
      </div>
      <div className="brief-desk">
        <form onSubmit={onSubmit}>
          <label htmlFor="brief-line">Your brief</label>
          <textarea
            id="brief-line"
            rows={3}
            value={draft}
            onChange={(ev) => setDraft(ev.target.value)}
            placeholder="What do you want decided."
          />
          <button type="submit">Send to T-1</button>
        </form>
        {active ? (
          <article className={speaking ? 'brief-out is-live' : 'brief-out'}>
            <p className="eyebrow">{deskLabel(active.answer.desk)}</p>
            <p className="brief-asked">{active.asked}</p>
            {parts[0] ? <h3>{parts[0]}</h3> : null}
            {parts.slice(1).map((para, i) => (
              <p key={i}>{para}</p>
            ))}
          </article>
        ) : (
          <article className="brief-out brief-out--empty">
            <p className="eyebrow">Awaiting</p>
            <h3>The desk is open.</h3>
            <p>Choose an incoming brief or write your own. T-1 stays on the plaza until you put something in front of it.</p>
          </article>
        )}
        {turns.length > 1 ? (
          <ul className="brief-log">
            {turns.slice(1).map((turn) => (
              <li key={turn.id}>
                <span>{deskLabel(turn.answer.desk)}</span>
                {turn.asked}
              </li>
            ))}
          </ul>
        ) : null}
      </div>
    </section>
  )
}
